    static func words(for level: String) -> [StudyWord] {
        all.filter { $0.level == level && !isKatakanaOnly($0.kana) }
    }

    /// Katakana-only entries are usually direct loanwords. Keep the decks
    /// focused on Japanese vocabulary written in hiragana and/or kanji.
    private static func isKatakanaOnly(_ text: String) -> Bool {
        guard !text.isEmpty else { return false }
        return text.unicodeScalars.allSatisfy { scalar in
            let value = scalar.value
            return (0x30A0...0x30FF).contains(value) || (0xFF66...0xFF9F).contains(value)
        }
    }

    static func word(for level: String, at date: Date = .now) -> StudyWord {
        let deck = words(for: level)
        let day = Calendar.current.ordinality(of: .day, in: .year, for: date) ?? 0
        let hour = Calendar.current.component(.hour, from: date)
        return deck[(day * 24 + hour) % deck.count]
    }
}

